import { expect, expectStatus, test } from "../../fixtures";

// PLAT-412: the vendor update endpoint is being rewritten. Keep this skipped until it lands.
test.fixme("a vendor under review cannot be edited", { tag: "@VEN-09" }, async ({ apiAs }) => {
  // Arrange: a member creates a uniquely named vendor and submits it, moving it to in_review.
  const member = await apiAs("member");
  const name = `VEN-09 Acme Freight ${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

  const created = await member.post("/api/vendors", {
    data: { name, category: "logistics", contact_email: "ops@acmefreight-ven09.example" },
  });
  const vendor = await expectStatus<{ id: string }>(created, 201);

  const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
  const submittedVendor = await expectStatus<{ status: string }>(submitted, 200);
  expect(submittedVendor.status).toBe("in_review");

  // Act: attempt to change the contact email while the vendor is under review.
  const response = await member.patch(`/api/vendors/${vendor.id}`, {
    data: { contact_email: "billing@acmefreight.example" },
  });

  // Assert
  const body = await expectStatus<{ error: { code: string } }>(response, 409);
  expect(body.error.code).toBe("vendor_locked");
});
